function validState(v){return v&&v.schema===2&&Number.isFinite(v.width)&&v.width>=5&&v.width<=100&&Number.isFinite(v.depth)&&v.depth>=5&&v.depth<=100&&v.points?.length>=3&&v.points.length<=20&&v.points.every(p=>Number.isFinite(p.x)&&Number.isFinite(p.y)&&p.x>=0&&p.x<=1&&p.y>=0&&p.y<=1)&&Array.isArray(v.items)&&v.items.length<=150&&v.items.every(i=>CATALOG[i.kind]&&Number.isFinite(i.x)&&Number.isFinite(i.y)&&i.x>=0&&i.x<=1&&i.y>=0&&i.y<=1&&Number.isFinite(i.w)&&i.w>0&&i.w<=100&&Number.isFinite(i.h)&&i.h>0&&i.h<=100&&Number.isFinite(i.angle))&&Array.isArray(v.zones)&&v.zones.length<=100&&v.zones.every(z=>Array.isArray(z.points)&&z.points.length>=3&&z.points.length<=100&&z.points.every(p=>Number.isFinite(p.x)&&Number.isFinite(p.y)&&p.x>=0&&p.x<=1&&p.y>=0&&p.y<=1))&&Array.isArray(v.routes)&&v.routes.length<=100&&v.routes.every(r=>Array.isArray(r.points)&&r.points.length>=2&&r.points.length<=100&&r.points.every(p=>Number.isFinite(p.x)&&Number.isFinite(p.y)&&p.x>=0&&p.x<=1&&p.y>=0&&p.y<=1))&&MATERIALS[v.material]&&['spring','summer','autumn','winter'].includes(v.season)&&Number.isFinite(v.target)&&v.target>=1000&&v.target<=30000&&[0,10,15,20].includes(+v.reserve)&&Array.isArray(v.tasks)&&v.tasks.length===3&&Number.isInteger(v.step)&&v.step>=0&&v.step<(v.workflowVersion===2?9:6)&&Number.isFinite(v.version)&&Number.isFinite(v.curve)&&v.curve>=0&&v.curve<=.3&&typeof v.name==='string'&&v.name.length<=70&&validExtensions(v)}
async function initStorage(){try{db=await new Promise((resolve,reject)=>{const q=indexedDB.open('terra-studio',1);q.onupgradeneeded=()=>q.result.createObjectStore('project');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error)});const stored=await new Promise((resolve,reject)=>{const q=db.transaction('project').objectStore('project').get('active');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error)});if(stored&&validState(stored.state)){S=stored.state;upgradeProject();photoData=stored.photo||null;photoMode=false;renderAll(true);notify('Your garden is back, just where you left it.')}}catch(e){notify('Device storage is unavailable. Download your project to keep a copy.')}}
