function bounds(){const ratio=S.width/S.depth;let w=670,h=w/ratio;if(h>410){h=410;w=h*ratio}return{x:(850-w)/2,y:(620-h)/2-6,w,h,scale:w/S.width}}
function xy(p,b=bounds()){return{x:b.x+p.x*b.w,y:b.y+p.y*b.h}}
function vertices(){return S.points.map(p=>({...p}))}
function roundedSegments(){const ps=vertices();return ps.map((p,i)=>{const prev=ps[(i+ps.length-1)%ps.length],next=ps[(i+1)%ps.length],t=p.sharp?0:S.curve;return{start:{x:p.x+(prev.x-p.x)*t,y:p.y+(prev.y-p.y)*t},corner:p,end:{x:p.x+(next.x-p.x)*t,y:p.y+(next.y-p.y)*t}}})}
function borderSamples(){if(S.shape!=='curve')return vertices();const arr=[];for(const s of roundedSegments()){for(let j=0;j<=12;j++){const t=j/12;arr.push({x:(1-t)*(1-t)*s.start.x+2*(1-t)*t*s.corner.x+t*t*s.end.x,y:(1-t)*(1-t)*s.start.y+2*(1-t)*t*s.corner.y+t*t*s.end.y})}}return arr}
function areaOf(ps){return Math.abs(ps.reduce((s,p,i)=>s+p.x*ps[(i+1)%ps.length].y-ps[(i+1)%ps.length].x*p.y,0))/2*S.width*S.depth}
function inside(p,poly=borderSamples()){let c=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){let a=poly[i],b=poly[j];if(((a.y>p.y)!==(b.y>p.y))&&(p.x<(b.x-a.x)*(p.y-a.y)/(b.y-a.y)+a.x))c=!c}return c}
function polygonArea(ps){return Math.abs(ps.reduce((s,p,i)=>s+p.x*ps[(i+1)%ps.length].y-ps[(i+1)%ps.length].x*p.y,0))/2}
// Union of soil zones clipped to the boundary, estimated by deterministic grid sampling.
function soilArea(){if(!S.zones.length)return 0;let count=0,n=100,border=borderSamples();for(let y=0;y<n;y++)for(let x=0;x<n;x++){let p={x:(x+.5)/n,y:(y+.5)/n};if(inside(p,border)&&S.zones.some(z=>inside(p,z.points)))count++}return count/n/n*S.width*S.depth}
function estimate(){return withLabor(projectEstimate())}
function pathFor(ps,b=bounds(),curved=false){if(!ps.length)return'';if(curved){const seg=roundedSegments(),first=xy(seg[0].start,b);let d=`M${first.x},${first.y}`;seg.forEach((s,i)=>{const c=xy(s.corner,b),e=xy(s.end,b),next=xy(seg[(i+1)%seg.length].start,b);d+=` Q${c.x},${c.y} ${e.x},${e.y} L${next.x},${next.y}`});return d+' Z'}const first=xy(ps[0],b);return`M${first.x},${first.y}`+ps.slice(1).map(p=>{const q=xy(p,b);return` L${q.x},${q.y}`}).join('')+' Z'}
