if(kind==='bbq')return `<rect x="-30" y="-45" width="60" height="28" rx="5" fill="#3d503f" stroke="#273f30"/><path d="M-24-17v28m48-28v28M-30-40h60" stroke="#384c38" stroke-width="3"/><rect x="-20" y="-50" width="40" height="7" rx="3" fill="#859078"/><circle cx="-18" cy="-21" r="2" fill="#d5c09c"/><circle cx="-8" cy="-21" r="2" fill="#d5c09c"/>`;
if(kind==='pot')return `<path d="M-24-30h48L17 6h-34Z" fill="#b36142" stroke="#7f4b34"/><ellipse cy="-30" rx="24" ry="7" fill="#ce8d62" stroke="#7f4b34"/><path d="M0-31q-29-7-18-30 17 8 18 30m0 0q30-10 22-31-19 7-22 31m0-1q-9-30 2-40 13 20-2 40" fill="${g}" stroke="#3f613b"/>`;
