function toNorm(e){const svg=$('#garden'),pt=new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse()),b=bounds();return{x:clamp((pt.x-b.x)/b.w,0,1),y:clamp((pt.y-b.y)/b.h,0,1)}}
$('#garden').addEventListener('pointerdown',e=>{if(e.button!==0)return;const p=toNorm(e);if(tool==='soil'||tool==='route'||tool==='path'||tool==='string'){if(draft.length>=50){notify('Finish this shape before adding more points.');return}draft.push(p);renderCanvas();renderControls();return}const it=e.target.closest('[data-item-id]'),v=e.target.closest('[data-vertex-id]'),zv=e.target.closest('[data-zone-vertex]'),zone=e.target.closest('[data-zone-id]'),route=e.target.closest('[data-route-id]'),path=e.target.closest('[data-path-id]'),rv=e.target.closest('[data-route-vertex]'),strand=e.target.closest('[data-string-id]'),sv=e.target.closest('[data-string-vertex]');if(rv&&route){selection={type:'route',id:route.dataset.routeId};drag={type:'routepoint',id:selection.id,index:+rv.dataset.routeVertex,start:p,before:clone(S)}}else if(sv&&strand){selection={type:'string',id:strand.dataset.stringId};drag={type:'stringpoint',id:selection.id,index:+sv.dataset.stringVertex,start:p,before:clone(S)}}else if(strand){selection={type:'string',id:strand.dataset.stringId}}else if(v){drag={type:'boundary',index:+v.dataset.vertexId,start:p,before:clone(S)};selection=null}else if(zv&&selection?.type==='zone'){drag={type:'zone',id:selection.id,index:+zv.dataset.zoneVertex,start:p,before:clone(S)}}else if(it){selection={type:'item',id:it.dataset.itemId};const o=S.items.find(i=>i.id===selection.id);drag={type:'item',id:o.id,start:p,x:o.x,y:o.y,before:clone(S)}}else if(path&&[1,4,5].includes(S.step)){selection={type:'path',id:path.dataset.pathId}}else if(route){selection={type:'route',id:route.dataset.routeId}}else if(zone&&[1,4,5].includes(S.step)){selection={type:'zone',id:zone.dataset.zoneId}}else selection=null;if(drag){$('#garden').setPointerCapture(e.pointerId);e.preventDefault()}renderCanvas();renderInspector()});
$('#garden').addEventListener('pointermove',e=>{if(!drag)return;const p=toNorm(e);if(drag.type==='routepoint'){S.routes.find(r=>r.id===drag.id).points[drag.index]=p}else if(drag.type==='stringpoint'){S.strings.find(s=>s.id===drag.id).points[drag.index]=p}else if(drag.type==='boundary'){let pts=clone(S.points);pts[drag.index]={...pts[drag.index],...p};if(simplePolygon(pts))S.points=pts}else if(drag.type==='item'){const i=S.items.find(i=>i.id===drag.id);i.x=clamp(drag.x+p.x-drag.start.x,0,1);i.y=clamp(drag.y+p.y-drag.start.y,0,1)}else if(drag.type==='zone'){const z=S.zones.find(z=>z.id===drag.id),pts=clone(z.points);pts[drag.index]=p;if(simplePolygon(pts))z.points=pts}renderCanvas()});
