$('#photo-input').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>15*1024*1024){notify('Choose a JPG, PNG or WebP image under 15 MB.');e.target.value='';return}try{const bitmap=await createImageBitmap(file),scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();photoData=canvas.toDataURL('image/jpeg',.85);photoMode=true;location.hash='studio';renderAll(true);await save(false);notify('Photo added privately. Mark soil in Hardscape. Enter measured dimensions separately.')}catch(err){notify('This image could not be opened. Try a different JPG or PNG.')}e.target.value=''};
